#import <UIKit/UIKit.h>
#include <iiGUI/DesktopCommon.h>
namespace ii::gui {
namespace {NSString* native(std::string_view s){return [[NSString alloc] initWithBytes:s.data() length:s.size() encoding:NSUTF8StringEncoding];}}
namespace detail {
core::Result<ClipboardContent> read_pasteboard(void*){if(!NSThread.isMainThread)return core::fail(core::ErrorCode::wrong_executor,"Clipboard requires main thread");auto board=UIPasteboard.generalPasteboard;ClipboardContent value;if(board.string)value.text=board.string.UTF8String;if(board.URL)value.url=board.URL.absoluteString.UTF8String;for(NSString* type in @[@"public.png",@"public.jpeg",@"public.tiff"]){auto data=[board dataForPasteboardType:type];if(!data)continue;if(data.length>64*1024*1024)return core::fail(core::ErrorCode::out_of_range,"Clipboard image exceeds limit");auto p=static_cast<const std::uint8_t*>(data.bytes);value.image.assign(p,p+data.length);value.image_mime=[type isEqualToString:@"public.png"]?"image/png":[type isEqualToString:@"public.jpeg"]?"image/jpeg":"image/tiff";break;}return value;}
}
core::Result<ClipboardContent> read_clipboard(){return detail::read_pasteboard(nullptr);}
core::Result<void> write_clipboard(const ClipboardContent& value){if(!NSThread.isMainThread)return core::fail(core::ErrorCode::wrong_executor,"Clipboard requires main thread");if(!detail::valid_clipboard(value))return core::fail(core::ErrorCode::invalid_argument,"Invalid clipboard payload");if(!value.files.empty())return core::fail(core::ErrorCode::unsupported,"Use the iPadOS document picker to share files");NSMutableDictionary* item=[NSMutableDictionary new];if(!value.text.empty())item[@"public.utf8-plain-text"]=native(value.text);if(!value.url.empty())item[@"public.url"]=[NSURL URLWithString:native(value.url)];if(!value.image.empty())item[value.image_mime=="image/png"?@"public.png":value.image_mime=="image/jpeg"?@"public.jpeg":@"public.tiff"]=[NSData dataWithBytes:value.image.data() length:value.image.size()];UIPasteboard.generalPasteboard.items=@[item];return {};}
core::Result<void> open_external_url(std::string_view url){if(!NSThread.isMainThread)return core::fail(core::ErrorCode::wrong_executor,"URL opening requires main thread");if(!detail::valid_external_url(url))return core::fail(core::ErrorCode::invalid_argument,"Expected a web, mail, or Society account URL");[UIApplication.sharedApplication openURL:[NSURL URLWithString:native(url)] options:@{} completionHandler:nil];return {};}
}
